<p class="lead">Manage platform configuration and account access. Donors, receivers and volunteers need no admin approval.</p>
<div class="metric-grid"><article class="panel metric"><p>Accounts</p><strong><?= count($data['accounts']) ?></strong></article><article class="panel metric"><p>Pending email deliveries</p><strong><?= e($data['mail']['pending'] ?? 0) ?></strong></article><article class="panel metric"><p>Exhausted email retries</p><strong><?= e($data['mail']['failed'] ?? 0) ?></strong></article></div>
<article class="panel spaced"><h2>Accounts</h2><div class="table-scroll"><table><thead><tr><th>Name / email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach ($data['accounts'] as $account): ?><tr><td><?= e($account['name']) ?><small><?= e($account['email']) ?></small></td><td><?= e($account['role_name']) ?></td><td><?php badge($account['status']); ?></td><td><?php if ((int)$account['id']!==(int)$user['id']): ?><form data-api="/api/admin/account" data-confirm="Change this account’s access status?"><input type="hidden" name="id" value="<?= e($account['id']) ?>"><input type="hidden" name="status" value="<?= $account['status']==='active' ? 'suspended' : 'active' ?>"><?php formend($account['status']==='active' ? 'Suspend' : 'Restore access'); ?><?php else: ?>Your account<?php endif ?></td></tr><?php endforeach ?></tbody></table></div></article>
<div class="dashboard-grid spaced"><article class="panel"><h2>Food categories</h2><form data-api="/api/admin/category"><?php field('name','New category name','text','','required maxlength="100"');formend('Add category'); ?><?php foreach ($data['all_categories'] as $category): ?><details><summary><?= e($category['name']) ?> · <?= $category['active'] ? 'Active' : 'Inactive' ?></summary><form data-api="/api/admin/category"><input type="hidden" name="id" value="<?= e($category['id']) ?>"><?php field('name','Category name','text',$category['name'],'required');checkfield('active','Available for new listings',(bool)$category['active']);formend(); ?></details><?php endforeach ?></article><article class="panel"><h2>Impact estimates</h2><form data-api="/api/admin/settings"><?php field('meal_mass_kg','Estimated kilograms per meal','number',0.4,'required min="0.01" max="10" step="0.01"');formend('Save conversion factor'); ?><h2 class="section-title">Matching configuration</h2><p>Current: <?= e($data['configuration']['version']) ?></p><?php require BASE_PATH . '/resources/views/algorithm-form.php'; ?></article></div>
<article class="panel spaced"><h2>Versioned safety-screening rules</h2><p>Mandatory handling, packaging and use-by checks always apply. Add numerical limits only with applicable guidance and a source URL. Updating a rule does not retroactively certify an existing listing; eligibility is checked again at matching and acceptance.</p><?php foreach ($data['rules'] as $rule):$parameters=json_decode($rule['parameters'],true); ?><details><summary><?= e($rule['category_name']) ?> · <?= e($rule['version']) ?></summary><form data-api="/api/admin/safety"><input type="hidden" name="category_id" value="<?= e($rule['category_id']) ?>"><?php checkfield('require_temperature','Measured temperature required',!empty($parameters['require_temperature']));field('max_age_minutes','Maximum preparation age (minutes; blank means no configured limit)','number',$parameters['max_age_minutes'] ?? '', 'min="1" max="525600"');field('min_temperature','Minimum temperature (°C; optional)','number',$parameters['min_temperature'] ?? '', 'min="-100" max="150" step="0.1"');field('max_temperature','Maximum temperature (°C; optional)','number',$parameters['max_temperature'] ?? '', 'min="-100" max="150" step="0.1"');field('source_url','Applicable guidance URL','url',$rule['source_url'],'required');formend('Save new rule version'); ?></details><?php endforeach ?></article>
<article class="panel spaced"><h2>Administrative & security audit</h2><ul class="activity-list"><?php foreach ($data['audit'] as $event): ?><li><span><?= e($event['name'] ?? 'System') ?> · <?= e($event['event']) ?><small><?= e($event['context']) ?></small></span><?php stamp($event['created_at']); ?></li><?php endforeach ?></ul></article>
